contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address attacker, address newOwner) public payable {
        require(attacker != address(this));
        address ownerBefore = c.owner();
        require(ownerBefore != attacker);
        bool reverted;
        // top-level state-changing call must not be inside try; emulate via low-level? Not allowed on c directly.
        // Instead: attempt the call via try/catch is disallowed for state changes... use try at top level:
        reverted = false;
        try c.transferOwnership(newOwner) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.owner() == ownerBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        address before = c.owner();
        bool reverted;
        try c.owned() { reverted = false; } catch { reverted = true; }
        bool reverted2;
        try c.transferOwnership(caller) { reverted2 = false; } catch { reverted2 = true; }
        assert(reverted && reverted2 && c.owner() == before);
    }
    receive() external payable {}
}
